const out = [];
for (let i = 0; i < 10; i++) {
  if (window.__ensemble.getState().settings.onboarded) break;
  const all = [...document.querySelectorAll('button')].filter(b => !b.disabled);
  const find = re => all.find(b => re.test(b.textContent.trim()));
  const b = find(/^(Continue|Start using|Start with|Get started|Start working|Done|Finish|Open Ensemble)/) || find(/^Skip/);
  if (!b) break;
  out.push(b.textContent.trim().slice(0, 30));
  b.click();
  await new Promise(r => setTimeout(r, 900));
}
return 'clicked: ' + out.join(' > ');

const st = window.__ensemble;
window.__u = { chatId: st.getState().chatId, agents: null, tasks: null };
const U = window.__u;
const apply = () => st.setState(s => {
  const out = {};
  out.chats = s.chats.map(c => {
    if (c.id !== U.chatId) return c;
    let n = c;
    if (!c.ultra) n = { ...n, ultra: true };
    if (U.agents && !U.agents.every(a => (c.agents || []).some(x => x.id === a.id))) n = { ...n, agents: [...(c.agents || []).filter(x => !U.agents.some(a => a.id === x.id)), ...U.agents] };
    return n;
  });
  if (U.tasks) {
    const cur = s.tasks[U.chatId] || [];
    if (!U.tasks.every(t => cur.some(x => x.id === t.id))) out.tasks = { ...s.tasks, [U.chatId]: [...cur.filter(x => !U.tasks.some(t => t.id === x.id)), ...U.tasks] };
  }
  return out;
});
U.apply = apply;
st.subscribe(s => { const c = s.chats.find(c => c.id === U.chatId); if (!c) return; const miss = !c.ultra || (U.agents && !U.agents.every(a => (c.agents || []).some(x => x.id === a.id))) || (U.tasks && !U.tasks.every(t => (s.tasks[U.chatId] || []).some(x => x.id === t.id))); if (miss) setTimeout(apply, 0); });
apply();
return 'ultra on for ' + U.chatId;

const st = window.__ensemble; const U = window.__u; const s = st.getState(); const now = Date.now();
const lead = s.chats.find(c => c.id === U.chatId).leadId || s.settings.leadId || s.accounts.find(a => a.enabled).id;
const accents = ['teal', 'blue', 'violet', 'green', 'amber', 'rose', 'slate', 'teal'];
const roles = ['Pricing of five rivals', 'Checkout patterns', 'Payment provider docs', 'Accessibility rules', 'Tax and VAT', 'Annual discounts', 'Conversion studies', 'Refund policies'];
const agents = [];
const mk = (id, name, by, depth, accent, role, base) => ({ id, name, provider: 'claude', accent, enabled: true, role, spawned: { chatId: U.chatId, base: base || lead, by, depth, at: now } });
for (let i = 0; i < 8; i++) agents.push(mk('scout-' + i, 'Scout ' + (i + 2), lead, 1, accents[i], roles[i]));
agents.push(mk('builder-a', 'Builder A', lead, 1, 'clay', 'Version A of the page'));
agents.push(mk('builder-b', 'Builder B', lead, 1, 'blue', 'Version B of the page'));
agents.push(mk('judge', 'Judge', lead, 1, 'slate', 'Scores every version'));
agents.push(mk('sub-1', 'Tester', 'builder-a', 2, 'green', 'Runs the checkout tests'));
agents.push(mk('sub-2', 'Reviewer', 'builder-a', 2, 'rose', 'Reads the diff cold'));
agents.push(mk('sub-3', 'Renderer', 'builder-b', 2, 'amber', 'Renders each direction'));
const tasks = [];
const t = (id, from, to, status, title) => tasks.push({ id, chatId: U.chatId, title, brief: title, from, to, status, createdAt: now - 60000 });
agents.forEach((a, i) => t('ft-' + i, a.spawned.by, a.id, i < 3 ? 'done' : i % 3 === 0 ? 'queued' : 'running', a.role));
U.agents = agents; U.tasks = tasks; U.apply();
const busy = ['scout-3', 'scout-4', 'scout-5', 'scout-6', 'builder-a', 'builder-b', 'sub-1', 'sub-3'];
const acts = { 'scout-3': 'Reading the WCAG checklist', 'builder-a': 'Writing src/pages/Pricing.tsx', 'builder-b': 'Trying a three-column layout', 'sub-1': 'Running the checkout tests', 'sub-3': 'Rendering direction 2' };
st.setState(x => ({ agents: { ...x.agents, ...Object.fromEntries(busy.map(id => [U.chatId + ':' + id, { chatId: U.chatId, accountId: id, phase: id === 'sub-3' ? 'tool' : 'thinking', activity: acts[id] || 'Searching the web', queued: 0, turnStartedAt: now - 30000 }])) } }));
return 'agents ' + agents.length + ', tasks ' + tasks.length;

