const a = strip.getBoundingClientRect(); const b = sc.getBoundingClientRect();
const probe = document.elementFromPoint(b.left + b.width / 2, Math.max(a.bottom, b.top) + 3);
const under = document.elementFromPoint(b.left + 60, a.bottom - 4);
return `strip ${Math.round(a.top)}-${Math.round(a.bottom)} | scroller top ${Math.round(b.top)} | gap ${Math.round(b.top - a.bottom)} | below strip: ${probe && probe.closest('[data-network-strip]') ? 'STRIP' : probe && sc.contains(probe) ? 'transcript' : probe?.tagName} | inside strip bottom: ${under && sc.contains(under) ? 'TRANSCRIPT (overlap)' : 'strip'} | scrollTop ${Math.round(sc.scrollTop)}`;

